#!/usr/bin/env python3
from pathlib import Path
import datetime,hashlib,json
OUT=Path(__file__).resolve().parent
DEST=OUT/'source-action-findings'
SOURCE=OUT/'staging/verification/component/source/vm'
def sha(b):return hashlib.sha256(b).hexdigest()
def write(n,d):(DEST/n).write_text(json.dumps(d,indent=2,sort_keys=True)+'\n')
def main():
 DEST.mkdir(exist_ok=False)
 for n in ['accounting.json','ACCOUNTING.md']:(DEST/('candidate-'+n)).write_bytes((OUT/'candidate-evidence'/n).read_bytes())
 b=(SOURCE/'src/experimental_swift_reactor/cache.rs').read_bytes();excerpt=''.join(b.decode().splitlines(keepends=True)[157:182])
 write('original-owner-allocator.json',{'schema':1,'path':'src/experimental_swift_reactor/cache.rs','source_sha256':sha(b),'original_source_unchanged_except_private_module_append':True,'start_line':158,'end_line':182,'excerpt':excerpt,'excerpt_sha256':sha(excerpt.encode()),'closure':'|n| n.checked_add(1)','standard_call':'AtomicU64::try_update','new_arbitrary_callback_seam':False})
 write('official-library-evidence.json',{'schema':1,'retrieved_at_date':'2026-10-26','retrieval_tool':'web.run search and open/find','local_official_document_available':False,'official_docs_url':'https://doc.rust-lang.org/stable/core/sync/atomic/type.AtomicU64.html','official_docs_short_quote':'This may call the function multiple times','official_source_url':'https://doc.rust-lang.org/stable/src/core/sync/atomic.rs.html','official_source_display_lines':[3488,3489],'official_source_short_excerpts':['while let Some(next) = f(prev) {','match self.compare_exchange_weak(prev, next, set_order, fetch_order) {'],'observation':'Official current standard documentation/source allow repeated FnMut evaluation during atomic retry; this evidence does not measure or hash the installed compiled standard library or prove a concrete retry count.'})
 accounting=json.loads((OUT/'candidate-evidence/accounting.json').read_text());assert sum(t['total'] for t in accounting['source_action_terms'])==521088
 write('finding.json',{'schema':1,'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'kind':'Unqualified logical source-action scalar pending explicit unit selection','candidate_seal_sha256':'50d1c32174ee4cbcade6095039261ea0ff8eed05680322bfb59b5de0dd4cd8b1','candidate_source_tree_sha256':'71a00fde8a43aef5a7e6104932d3f0ca10a5989fb686c99828937b05aa363c7c','candidate_fields':{'new_and_original_construction_cleanup_source_action_upper_bound':521088,'accepted_row_source_actions_plus_requested_IO':450652288,'joined_source_actions_plus_requested_IO_upper_bound':451173376,'source_action_unit':accounting['source_action_unit']},'derivation':accounting['source_action_terms'],'concrete_gap':'The unchanged original constructor invokes std AtomicU64::try_update with an authored pure checked-add closure; the standard operation can reevaluate this closure. A finite count of one callsite does not establish a count of actual authored callback evaluations. Existing library/kernel exclusions need an explicit abstraction boundary if the scalar is retained. No universal callback/CPU/atomic retry bound is proved.','proposed_unit_options':[{'unit':'Abstract callsite actions plus cumulative requested I/O','definition':'Count each selected standard primitive call and closed pure owner-ID callback as one abstract operation; bound explicit new/original source loops separately. Explicitly exclude library/kernel/allocator/atomic retries and retry-driven callback reevaluation.','obligation':'Root must explicitly select this reduced unit and prohibit interpreting451173376 as an upper bound on all actual authored callback executions, CPU instructions, time, VM debits or arbitrary concurrent callers. Reconcile the accepted row450652288 term under the same unit.'},{'unit':'All actual authored source evaluations including callback reevaluation','definition':'Count every actual invocation of the checked-add closure, including standard-library retry driven invocations.','obligation':'No finite numeric bound is established by this packet. A separate proof/qualification would need to bound retry/reevaluation behavior for the actual source/tool/target/context, or a separately selected implementation change. None is authorized or performed here.'}],'unchanged_independent_qualifications':{'source_object_union_production':197880,'source_object_union_unit':197928,'corrected_foundations':[269080,269616],'healthy_cleanup_zero':True,'unit_only_fault_quarantine_bytes':331496,'unit_only_fault_quarantine_tickets':1,'fresh_selected_and_independent_commands':149,'compiler_observations':44,'requested_row_IO_bound':81920000,'maximum_row_attempts':20000},'no_code_caps_deadlines_expectations_or_frozen_candidate_change':True,'logical_scalar_accepted':False,'root_amendment_pending':True,'full_component_root_accepted':False})
 members=[]
 for p in sorted(DEST.rglob('*')):
  if p.is_file():b=p.read_bytes();members.append({'path':str(p.relative_to(DEST)),'bytes':len(b),'sha256':sha(b)})
 write('seal.json',{'schema':1,'scope':'Exact independent source-action unit finding; numeric scalar unqualified','member_count':len(members),'total_bytes':sum(m['bytes'] for m in members),'members':members,'excluded':['seal.json','seal.sha256']})
 digest=sha((DEST/'seal.json').read_bytes());(DEST/'seal.sha256').write_text(digest+'  seal.json\n');print(f'SOURCE ACTION FINDING frozen {len(members)} members seal {digest}')
if __name__=='__main__':main()
